    "language": "polish",
    "number": 499,
    "title": "Za Jezusa Pana wzorem",
    "source_url": "https://hymnary.org/hymn/SE2002/499"
  },
  {
    "language": "polish",
    "number": 500,
    "title": "Boże kochany",
    "source_url": "https://hymnary.org/hymn/SE2002/500"
  },
  {
    "language": "polish",
    "number": 501,
    "title": "Cichy zapada zmrok",
    "source_url": "https://hymnary.org/hymn/SE2002/501"
  },
  {
    "language": "polish",
    "number": 502,
    "title": "Czeladka Twa wieczorem",
    "source_url": "https://hymnary.org/hymn/SE2002/502"
  },
  {
    "language": "polish",
    "number": 503,
    "title": "Dzienne prace, trudy dzienne",
    "source_url": "https://hymnary.org/hymn/SE2002/503"
  },
  {
    "language": "polish",
    "number": 504,
    "title": "Dzień kończy się, coś dał go Panie",
    "source_url": "https://hymnary.org/hymn/SE2002/504"
  },
  {
    "language": "polish",
    "number": 505,
    "title": "Gdy się dzień kończy juȧ",
    "source_url": "https://hymnary.org/hymn/SE2002/505"
  },
  {
    "language": "polish",
    "number": 507,
    "title": "Idzie noc",
    "source_url": "https://hymnary.org/hymn/SE2002/507"
  },
  {
    "language": "polish",
    "number": 508,
    "title": "Jest ze mną Pan, gdy wieczór zbliźa się",
    "source_url": "https://hymnary.org/hymn/SE2002/508"
  },
  {
    "language": "polish",
    "number": 509,
    "title": "Już księżyc wzeszedł jasno",
    "source_url": "https://hymnary.org/hymn/SE2002/509"
  },
  {
    "language": "polish",
    "number": 510,
    "title": "Już ostatni za górami promień słońca zgasł",
    "source_url": "https://hymnary.org/hymn/SE2002/510"
  },
  {
    "language": "polish",
    "number": 511,
    "title": "Już wieczór się przybliża",
    "source_url": "https://hymnary.org/hymn/SE2002/511"
  },
  {
    "language": "polish",
    "number": 512,
    "title": "Kiedy w jasną, spokojną cichą noc",
    "source_url": "https://hymnary.org/hymn/SE2002/512"
  },
  {
    "language": "polish",
    "number": 513,
    "title": "Na zachód dzień się chyli",
    "source_url": "https://hymnary.org/hymn/SE2002/513"
  },
  {
    "language": "polish",
    "number": 514,
    "title": "O gwiazdeczko z niebios włości oświeć cerce me!",
    "source_url": "https://hymnary.org/hymn/SE2002/514"
  },
  {
    "language": "polish",
    "number": 515,
    "title": "O Panie, zostań ze meną",
    "source_url": "https://hymnary.org/hymn/SE2002/515"
  },
  {
    "language": "polish",
    "number": 516,
    "title": "Ocknij się, o duszo moja",
    "source_url": "https://hymnary.org/hymn/SE2002/516"
  },
  {
    "language": "polish",
    "number": 517,
    "title": "Przeminął dnia jasnego",
    "source_url": "https://hymnary.org/hymn/SE2002/517"
  },
  {
    "language": "polish",
    "number": 519,
    "title": "Spoczęly lasy, siola",
    "source_url": "https://hymnary.org/hymn/SE2002/519"
  },
  {
    "language": "polish",
    "number": 520,
    "title": "Spracowany idę spać",
    "source_url": "https://hymnary.org/hymn/SE2002/520"
  },
  {
    "language": "polish",
    "number": 521,
    "title": "Tyś mnie wziął, Panie",
    "source_url": "https://hymnary.org/hymn/SE2002/521"
  },
  {
    "language": "polish",
    "number": 522,
    "title": "Wszystkie nasze dzienne sprawy",
    "source_url": "https://hymnary.org/hymn/SE2002/522"
  },
  {
    "language": "polish",
    "number": 523,
    "title": "Zapada już mrok",
    "source_url": "https://hymnary.org/hymn/SE2002/523"
  },
  {
    "language": "polish",
    "number": 525,
    "title": "Chwal Boga ufnym ṡpiewem",
    "source_url": "https://hymnary.org/hymn/SE2002/525"
  },
  {
    "language": "polish",
    "number": 526,
    "title": "Chwal, dziękuj Bogu",
    "source_url": "https://hymnary.org/hymn/SE2002/526"
  },
  {
    "language": "polish",
    "number": 527,
    "title": "Cóż tak zapominacie",
    "source_url": "https://hymnary.org/hymn/SE2002/527"
  },
  {
    "language": "polish",
    "number": 528,
    "title": "Do Ciebie modly ślemy",
    "source_url": "https://hymnary.org/hymn/SE2002/528"
  },
  {
    "language": "polish",
    "number": 529,
    "title": "Działaj, bo noc nadejdzie",
    "source_url": "https://hymnary.org/hymn/SE2002/529"
  },
  {
    "language": "polish",
    "number": 530,
    "title": "Jednak Emanuel, Pan nasz, króluje!",
    "source_url": "https://hymnary.org/hymn/SE2002/530"
  },
  {
    "language": "polish",
    "number": 531,
    "title": "Mam wspaniałego Zbawiciela",
    "source_url": "https://hymnary.org/hymn/SE2002/531"
  },
  {
    "language": "polish",
    "number": 532,
    "title": "Naprzód krocz",
    "source_url": "https://hymnary.org/hymn/SE2002/532"
  },
  {
    "language": "polish",
    "number": 533,
    "title": "O Panie, z nami bądź w ten czas",
    "source_url": "https://hymnary.org/hymn/SE2002/533"
  },
  {
    "language": "polish",
    "number": 534,
    "title": "Pasterzu dobry nasz",
    "source_url": "https://hymnary.org/hymn/SE2002/534"
  },
  {
    "language": "polish",
    "number": 535,
    "title": "Posyłam was do pracy bez nagrody",
    "source_url": "https://hymnary.org/hymn/SE2002/535"
  },
  {
    "language": "polish",
    "number": 536,
    "title": "Słuchaj, młodzieży kwitnąca, nadziejo przyszłości!",
    "source_url": "https://hymnary.org/hymn/SE2002/536"
  },
  {
    "language": "polish",
    "number": 537,
    "title": "Ṡwiatło nieṡć tam gdzie ciemność trwa",
    "source_url": "https://hymnary.org/hymn/SE2002/537"
  },
  {
    "language": "polish",
    "number": 538,
    "title": "Teraz, w młodych życia latach",
    "source_url": "https://hymnary.org/hymn/SE2002/538"
  },
  {
    "language": "polish",
    "number": 539,
    "title": "Tu miejsca dość",
    "source_url": "https://hymnary.org/hymn/SE2002/539"
  },
  {
    "language": "polish",
    "number": 540,
    "title": "Zbawczą potęgą",
    "source_url": "https://hymnary.org/hymn/SE2002/540"
  },
  {
    "language": "polish",
    "number": 541,
    "title": "Zbudź, Panie, ducha ojców wiary",
    "source_url": "https://hymnary.org/hymn/SE2002/541"
  },
  {
    "language": "polish",
    "number": 542,
    "title": "Bądźmy jedno w Panu, bädźmy jedno w Nim",
    "source_url": "https://hymnary.org/hymn/SE2002/542"
  },
  {
    "language": "polish",
    "number": 543,
    "title": "Bo nikt nie ma z nas tego, co mamy razem",
    "source_url": "https://hymnary.org/hymn/SE2002/543"
  },
  {
    "language": "polish",
    "number": 544,
    "title": "Chryste, obrońco Kościoła swojego",
    "source_url": "https://hymnary.org/hymn/SE2002/544"
  },
  {
    "language": "polish",
    "number": 545,
    "title": "Dawco wiernych sług Syjonu!",
    "source_url": "https://hymnary.org/hymn/SE2002/545"
  },
  {
    "language": "polish",
    "number": 546,
    "title": "Drzewko jedno znam zielone",
    "source_url": "https://hymnary.org/hymn/SE2002/546"
  },
  {
    "language": "polish",
    "number": 547,
    "title": "Głowo Kościola, nasz Zbawco i Panie",
    "source_url": "https://hymnary.org/hymn/SE2002/547"
  },
  {
    "language": "polish",
    "number": 548,
    "title": "Jeszcze to nie nadszedł czas",
    "source_url": "https://hymnary.org/hymn/SE2002/548"
  },
  {
    "language": "polish",
    "number": 549,
    "title": "Ludu Pański, w doczesności",
    "source_url": "https://hymnary.org/hymn/SE2002/549"
  },
  {
    "language": "polish",
    "number": 550,
    "title": "Miasto Boże mocno stoi",
    "source_url": "https://hymnary.org/hymn/SE2002/550"
  },
  {
    "language": "polish",
    "number": 551,
    "title": "Mocny grunt stoi!",
    "source_url": "https://hymnary.org/hymn/SE2002/551"
  },
  {
    "language": "polish",
    "number": 552,
    "title": "Na skale Kościół stoi",
    "source_url": "https://hymnary.org/hymn/SE2002/552"
  },
  {
    "language": "polish",
    "number": 553,
    "title": "Na swój święty Kościoł cały",
    "source_url": "https://hymnary.org/hymn/SE2002/553"
  },
  {
    "language": "polish",
    "number": 554,
    "title": "O Boźe, przed oblicze Twe",
    "source_url": "https://hymnary.org/hymn/SE2002/554"
  },
  {
    "language": "polish",
    "number": 555,
    "title": "O, jak pięknie w zgodzie żyć",
    "source_url": "https://hymnary.org/hymn/SE2002/555"
  },
  {
    "language": "polish",
    "number": 556,
    "title": "O, jak to dobrze i milo",
    "source_url": "https://hymnary.org/hymn/SE2002/556"
  },
  {
    "language": "polish",
    "number": 557,
    "title": "O, jak to mijsce jest rozkoszne",
    "source_url": "https://hymnary.org/hymn/SE2002/557"
  },
  {
    "language": "polish",
    "number": 558,
    "title": "O Jezu! Wszak to sprawa Twa",
    "source_url": "https://hymnary.org/hymn/SE2002/558"
  },
  {
    "language": "polish",
    "number": 559,
    "title": "O Jezu, zostań z nami",
    "source_url": "https://hymnary.org/hymn/SE2002/559"
  },
  {
    "language": "polish",
    "number": 561,
    "title": "Ochrzczeni w Chrystusie",
    "source_url": "https://hymnary.org/hymn/SE2002/561"
  },
  {
    "language": "polish",
    "number": 562,
    "title": "Opoką jest Kościoła",
    "source_url": "https://hymnary.org/hymn/SE2002/562"
  },
  {
    "language": "polish",
    "number": 563,
    "title": "Panie, przed którym",
    "source_url": "https://hymnary.org/hymn/SE2002/563"
  },
  {
    "language": "polish",
    "number": 564,
    "title": "Serca razem połączone",
    "source_url": "https://hymnary.org/hymn/SE2002/564"
  },
  {
    "language": "polish",
    "number": 565,
    "title": "Słońce prawdy, wzejdź wśród nas",
    "source_url": "https://hymnary.org/hymn/SE2002/565"
  },
  {
    "language": "polish",
    "number": 566,
    "title": "Świąta milość Jezusowa niech połączy nas",
    "source_url": "https://hymnary.org/hymn/SE2002/566"
  },
  {
    "language": "polish",
    "number": 567,
    "title": "Ty sam, Panie, dajesz z nieba",
    "source_url": "https://hymnary.org/hymn/SE2002/567"
  },
  {
    "language": "polish",
    "number": 568,
    "title": "W niebie i na ziemi tej",
    "source_url": "https://hymnary.org/hymn/SE2002/568"
  },
  {
    "language": "polish",
    "number": 569,
    "title": "Wszyscy, którzyṡmy się tu zebrali",
    "source_url": "https://hymnary.org/hymn/SE2002/569"
  },
  {
    "language": "polish",
    "number": 570,
    "title": "Z modłami, ze łzami wolamy do Pana",
    "source_url": "https://hymnary.org/hymn/SE2002/570"
  },
  {
    "language": "polish",
    "number": 571,
    "title": "Z radoṡcią pójdżcie z wszystkich stron",
    "source_url": "https://hymnary.org/hymn/SE2002/571"
  },
  {
    "language": "polish",
    "number": 572,
    "title": "Zanućmy pieśń wesołą",
    "source_url": "https://hymnary.org/hymn/SE2002/572"
  },
  {
    "language": "polish",
    "number": 573,
    "title": "Zjednoczył nas ze wszystkich ziem",
    "source_url": "https://hymnary.org/hymn/SE2002/573"
  },
  {
    "language": "polish",
    "number": 574,
    "title": "Złącz, Panie, milujących Cię",
    "source_url": "https://hymnary.org/hymn/SE2002/574"
  },
  {
    "language": "polish",
    "number": 575,
    "title": "Zwiąż Panie, razem nas, związ Panie",
    "source_url": "https://hymnary.org/hymn/SE2002/575"
  },
  {
    "language": "polish",
    "number": 576,
    "title": "Ach, Boże, mój Boże!",
    "source_url": "https://hymnary.org/hymn/SE2002/576"
  },
  {
    "language": "polish",
    "number": 577,
    "title": "Ach, Boże, spojrzyj z nieba już",
    "source_url": "https://hymnary.org/hymn/SE2002/577"
  },
  {
    "language": "polish",
    "number": 578,
    "title": "Aż dotąd mnie prowadził Bóg",
    "source_url": "https://hymnary.org/hymn/SE2002/578"
  },
  {
    "language": "polish",
    "number": 579,
    "title": "Bądż Panu cześć! Zanućcie pieśni chwaly",
    "source_url": "https://hymnary.org/hymn/SE2002/579"
  },
  {
    "language": "polish",
    "number": 580,
    "title": "Błogosław, duszo moja Panu swemu",
    "source_url": "https://hymnary.org/hymn/SE2002/580"
  },
  {
    "language": "polish",
    "number": 581,
    "title": "Błogsław Panu",
    "source_url": "https://hymnary.org/hymn/SE2002/581"
  },
  {
    "language": "polish",
    "number": 582,
    "title": "Chcę chwalić Boga dziś",
    "source_url": "https://hymnary.org/hymn/SE2002/582"
  },
  {
    "language": "polish",
    "number": 583,
    "title": "Chcę o Jezusie moim ṡpiewać",
    "source_url": "https://hymnary.org/hymn/SE2002/583"
  },
  {
    "language": "polish",
    "number": 584,
    "title": "Chwal, duszo moja, Pana",
    "source_url": "https://hymnary.org/hymn/SE2002/584"
  },
  {
    "language": "polish",
    "number": 586,
    "title": "Chwalę daj Panu, o duszo moja",
    "source_url": "https://hymnary.org/hymn/SE2002/586"
  },
  {
    "language": "polish",
    "number": 587,
    "title": "Czyż tron Twój, Panie uwielbiony",
    "source_url": "https://hymnary.org/hymn/SE2002/587"
  },
  {
    "language": "polish",
    "number": 588,
    "title": "Czyżbym nie miał ṡpiewać Bogu",
    "source_url": "https://hymnary.org/hymn/SE2002/588"
  },
  {
    "language": "polish",
    "number": 589,
    "title": "Dobroci, łaski pelny",
    "source_url": "https://hymnary.org/hymn/SE2002/589"
  },
  {
    "language": "polish",
    "number": 590,
    "title": "Dziękować Ci, Panie chcę",
    "source_url": "https://hymnary.org/hymn/SE2002/590"
  },
  {
    "language": "polish",
    "number": 591,
    "title": "Dziękuj Panu, dziękuj Mu",
    "source_url": "https://hymnary.org/hymn/SE2002/591"
  },
  {
    "language": "polish",
    "number": 592,
    "title": "Dziękujé Tobie, Zbawco mily",
    "source_url": "https://hymnary.org/hymn/SE2002/592"
  },
  {
    "language": "polish",
    "number": 593,
    "title": "Dziękujmy Bogu wraz",
    "source_url": "https://hymnary.org/hymn/SE2002/593"
  },
  {
    "language": "polish",
    "number": 594,
    "title": "Gdybym jęzków miał tycsiące",
    "source_url": "https://hymnary.org/hymn/SE2002/594"
  },
  {
    "language": "polish",
    "number": 595,
    "title": "Gloście radoṡnie wszyscy wraz",
    "source_url": "https://hymnary.org/hymn/SE2002/595"
  },
  {
    "language": "polish",
    "number": 596,
    "title": "Godzien jesteś",
    "source_url": "https://hymnary.org/hymn/SE2002/596"
  },
  {
    "language": "polish",
    "number": 597,
    "title": "Hymn wdzięczności plynie z duszy",
    "source_url": "https://hymnary.org/hymn/SE2002/597"
  },
  {
    "language": "polish",
    "number": 598,
    "title": "Ja do Ciebie, Ojcze w niebie",
    "source_url": "https://hymnary.org/hymn/SE2002/598"
  },
  {
    "language": "polish",
    "number": 599,
    "title": "Jezu, Ty niewysłowioną",
    "source_url": "https://hymnary.org/hymn/SE2002/599"
  },
  {
    "language": "polish",
    "number": 600,
    "title": "Królu nasz przedziwny",
    "source_url": "https://hymnary.org/hymn/SE2002/600"
  },
  {
    "language": "polish",
    "number": 601,
    "title": "Magnificat, magnificat",
    "source_url": "https://hymnary.org/hymn/SE2002/601"
  },
  {
    "language": "polish",
    "number": 602,
    "title": "Mój wiekuisty",
    "source_url": "https://hymnary.org/hymn/SE2002/602"
  },
  {
    "language": "polish",
    "number": 603,
    "title": "Niech będzie chwała i czesć i uwielbienie",
    "source_url": "https://hymnary.org/hymn/SE2002/603"
  },
  {
    "language": "polish",
    "number": 604,
    "title": "Nie opuść mnie",
    "source_url": "https://hymnary.org/hymn/SE2002/604"
  },
  {
    "language": "polish",
    "number": 605,
    "title": "Niech będzie Najwyższemu cześć",
    "source_url": "https://hymnary.org/hymn/SE2002/605"
  },
  {
    "language": "polish",
    "number": 606,
    "title": "Niech śpiew narodów brzmi na ziemi",
    "source_url": "https://hymnary.org/hymn/SE2002/606"
  },
  {
    "language": "polish",
    "number": 607,
    "title": "Niech w Panu się raduje ṡwiat",
    "source_url": "https://hymnary.org/hymn/SE2002/607"
  },
  {
    "language": "polish",
    "number": 608,
    "title": "O, chwałcie Pana!",
    "source_url": "https://hymnary.org/hymn/SE2002/608"
  },
  {
    "language": "polish",
    "number": 609,
    "title": "O dobry Ojcze, Boże",
    "source_url": "https://hymnary.org/hymn/SE2002/609"
  },
  {
    "language": "polish",
    "number": 610,
    "title": "O Panie, Tobie chcę zaśpiewać",
    "source_url": "https://hymnary.org/hymn/SE2002/610"
  },
  {
    "language": "polish",
    "number": 611,
    "title": "O Przedwiczny, Wiekuisty",
    "source_url": "https://hymnary.org/hymn/SE2002/611"
  },
  {
    "language": "polish",
    "number": 612,
    "title": "Oddajcie panu, bogu cześć",
    "source_url": "https://hymnary.org/hymn/SE2002/612"
  },
  {
    "language": "polish",
    "number": 613,
    "title": "Ojcze nasz, co jesteś w niebie",
    "source_url": "https://hymnary.org/hymn/SE2002/613"
  },
  {
    "language": "polish",
    "number": 614,
    "title": "Ojcze z niebios, Boże, Panie",
    "source_url": "https://hymnary.org/hymn/SE2002/614"
  },
  {
    "language": "polish",
    "number": 615,
    "title": "Pan dobry jest",
    "source_url": "https://hymnary.org/hymn/SE2002/615"
  },
  {
    "language": "polish",
    "number": 616,
    "title": "Pan Dobry jest!",
    "source_url": "https://hymnary.org/hymn/SE2002/616"
  },
  {
    "language": "polish",
    "number": 617,
    "title": "Panie Boże, niechże wszędzie",
    "source_url": "https://hymnary.org/hymn/SE2002/617"
  },
  {
    "language": "polish",
    "number": 618,
    "title": "Panie, wysluchać modlów chciej!",
    "source_url": "https://hymnary.org/hymn/SE2002/618"
  },
  {
    "language": "polish",
    "number": 619,
    "title": "Pieśń wznoszą usta, serce me",
    "source_url": "https://hymnary.org/hymn/SE2002/619"
  },
  {
    "language": "polish",
    "number": 620,
    "title": "Pochwal, mój duchu, Mocarza wielkiego wszechświata",
    "source_url": "https://hymnary.org/hymn/SE2002/620"
  },
  {
    "language": "polish",
    "number": 621,
    "title": "Rzeszo święta, serce swe",
    "source_url": "https://hymnary.org/hymn/SE2002/621"
  },
  {
    "language": "polish",
    "number": 622,
    "title": "Tobie, Panie, chcemy dziś",
    "source_url": "https://hymnary.org/hymn/SE2002/622"
  },
  {
    "language": "polish",
    "number": 623,
    "title": "Wierzyć mnie, Panie, ucz",
    "source_url": "https://hymnary.org/hymn/SE2002/623"
  },
  {
    "language": "polish",
    "number": 624,
    "title": "Winniśmy bogu hołd i dzięki",
    "source_url": "https://hymnary.org/hymn/SE2002/624"
  },
  {
    "language": "polish",
    "number": 625,
    "title": "Wspaniałym Panem Tyś",
    "source_url": "https://hymnary.org/hymn/SE2002/625"
  },
  {
    "language": "polish",
    "number": 626,
    "title": "Wszelki naród, wszelkie plemię",
    "source_url": "https://hymnary.org/hymn/SE2002/626"
  },
  {
    "language": "polish",
    "number": 627,
    "title": "Wszystko powidz Jezusowi",
    "source_url": "https://hymnary.org/hymn/SE2002/627"
  },
  {
    "language": "polish",
    "number": 628,
    "title": "Z calej swej duszy",
    "source_url": "https://hymnary.org/hymn/SE2002/628"
  },
  {
    "language": "polish",
    "number": 629,
    "title": "Zaśpiewaj, duszo moja",
    "source_url": "https://hymnary.org/hymn/SE2002/629"
  },
  {
    "language": "polish",
    "number": 630,
    "title": "Bóg dal zbawienie",
    "source_url": "https://hymnary.org/hymn/SE2002/630"
  },
  {
    "language": "polish",
    "number": 631,
    "title": "Bóg z łaski ten grzeszny ṡwiat tak umilował",
    "source_url": "https://hymnary.org/hymn/SE2002/631"
  },
  {
    "language": "polish",
    "number": 632,
    "title": "Choć dokoła ciemne mroki",
    "source_url": "https://hymnary.org/hymn/SE2002/632"
  },
  {
    "language": "polish",
    "number": 633,
    "title": "Cóż cudniejszego może być",
    "source_url": "https://hymnary.org/hymn/SE2002/633"
  },
  {
    "language": "polish",
    "number": 634,
    "title": "Cudowna Boża łaska ta",
    "source_url": "https://hymnary.org/hymn/SE2002/634"
  },
  {
    "language": "polish",
    "number": 635,
    "title": "Gdy ze mną Bóg stanie",
    "source_url": "https://hymnary.org/hymn/SE2002/635"
  },
  {
    "language": "polish",
    "number": 636,
    "title": "Jeden skarb bym posiść chciał",
    "source_url": "https://hymnary.org/hymn/SE2002/636"
  },
  {
    "language": "polish",
    "number": 637,
    "title": "Jezus grzesznych przyjąć chce!",
    "source_url": "https://hymnary.org/hymn/SE2002/637"
  },
  {
    "language": "polish",
    "number": 638,
    "title": "Kto chce, niech szuka innych dróg",
    "source_url": "https://hymnary.org/hymn/SE2002/638"
  },
  {
    "language": "polish",
    "number": 639,
    "title": "Mój jest Zbawiciel, ustały już żale",
    "source_url": "https://hymnary.org/hymn/SE2002/639"
  },
  {
    "language": "polish",
    "number": 640,
    "title": "Nic nie może szczęścia",
    "source_url": "https://hymnary.org/hymn/SE2002/640"
  },
  {
    "language": "polish",
    "number": 641,
    "title": "Niech cały się raduje ṡwiat",
    "source_url": "https://hymnary.org/hymn/SE2002/641"
  },
  {
    "language": "polish",
    "number": 642,
    "title": "O blogosławiony",
    "source_url": "https://hymnary.org/hymn/SE2002/642"
  },
  {
    "language": "polish",
    "number": 643,
    "title": "O Chryste, sprawiedliwość Twa",
    "source_url": "https://hymnary.org/hymn/SE2002/643"
  },
  {
    "language": "polish",
    "number": 644,
    "title": "O Miłości wieczna",
    "source_url": "https://hymnary.org/hymn/SE2002/644"
  },
  {
    "language": "polish",
    "number": 645,
    "title": "Pozostań z łaską swoją",
    "source_url": "https://hymnary.org/hymn/SE2002/645"
  },
  {
    "language": "polish",
    "number": 646,
    "title": "Przez wiele lat szukałem szczęścia w życiu mym",
    "source_url": "https://hymnary.org/hymn/SE2002/646"
  },
  {
    "language": "polish",
    "number": 647,
    "title": "Święty, ṡwięty, święty Boże",
    "source_url": "https://hymnary.org/hymn/SE2002/647"
  },
  {
    "language": "polish",
    "number": 648,
    "title": "Teraz życiem dła mej duszy",
    "source_url": "https://hymnary.org/hymn/SE2002/648"
  },
  {
    "language": "polish",
    "number": 649,
    "title": "Ufnością w Bogu wiara jest",
    "source_url": "https://hymnary.org/hymn/SE2002/649"
  },
  {
    "language": "polish",
    "number": 650,
    "title": "Ułaskwienia dostąpilem",
    "source_url": "https://hymnary.org/hymn/SE2002/650"
  },
  {
    "language": "polish",
    "number": 651,
    "title": "W Twoich rękach, Panie",
    "source_url": "https://hymnary.org/hymn/SE2002/651"
  },
  {
    "language": "polish",
    "number": 652,
    "title": "Wiem dobrze, w kogo wierzę",
    "source_url": "https://hymnary.org/hymn/SE2002/652"
  },
  {
    "language": "polish",
    "number": 653,
    "title": "Zbawienia \"z łaski\" mam dostąpić",
    "source_url": "https://hymnary.org/hymn/SE2002/653"
  },
  {
    "language": "polish",
    "number": 654,
    "title": "Znalazłem już ten port bezpieczny",
    "source_url": "https://hymnary.org/hymn/SE2002/654"
  },
  {
    "language": "polish",
    "number": 655,
    "title": "Będę Cię wielbił, mój Panie",
    "source_url": "https://hymnary.org/hymn/SE2002/655"
  },
  {
    "language": "polish",
    "number": 656,
    "title": "Bliżej, o bliżej wznieṡ mnie i tul",
    "source_url": "https://hymnary.org/hymn/SE2002/656"
  },
  {
    "language": "polish",
    "number": 658,
    "title": "Boże litości",
    "source_url": "https://hymnary.org/hymn/SE2002/658"
  },
  {
    "language": "polish",
    "number": 659,
    "title": "Bóg nasz ucieczką",
    "source_url": "https://hymnary.org/hymn/SE2002/659"
  },
  {
    "language": "polish",
    "number": 660,
    "title": "Bóg wierny jest",
    "source_url": "https://hymnary.org/hymn/SE2002/660"
  },
  {
    "language": "polish",
    "number": 661,
    "title": "Bóg wierny słowom swym",
    "source_url": "https://hymnary.org/hymn/SE2002/661"
  },
  {
    "language": "polish",
    "number": 662,
    "title": "Choć burza huczy wkoło nas",
    "source_url": "https://hymnary.org/hymn/SE2002/662"
  },
  {
    "language": "polish",
    "number": 663,
    "title": "\"Chodź do mnie juź\", Syn Boźy zwie",
    "source_url": "https://hymnary.org/hymn/SE2002/663"
  },
  {
    "language": "polish",
    "number": 664,
    "title": "Co Bög mój chce, niech stanie się",
    "source_url": "https://hymnary.org/hymn/SE2002/664"
  },
  {
    "language": "polish",
    "number": 665,
    "title": "Co czyni Bóg, jest dobrze tak",
    "source_url": "https://hymnary.org/hymn/SE2002/665"
  },
  {
    "language": "polish",
    "number": 666,
    "title": "Czekaj Pana swego, o duszo ma!",
    "source_url": "https://hymnary.org/hymn/SE2002/666"
  },
  {
    "language": "polish",
    "number": 667,
    "title": "Daj nam, Panie, wytrwać w czasie burz",
    "source_url": "https://hymnary.org/hymn/SE2002/667"
  },
  {
    "language": "polish",
    "number": 668,
    "title": "Dlaczego tak się trwożysz",
    "source_url": "https://hymnary.org/hymn/SE2002/668"
  },
  {
    "language": "polish",
    "number": 669,
    "title": "Dlaczego w twym oku tak często jest łza",
    "source_url": "https://hymnary.org/hymn/SE2002/669"
  },
  {
    "language": "polish",
    "number": 670,
    "title": "Dokąd mam się w trokach męczyć",
    "source_url": "https://hymnary.org/hymn/SE2002/670"
  },
  {
    "language": "polish",
    "number": 671,
    "title": "Dzień po dniu, dla każdej nowej chwili",
    "source_url": "https://hymnary.org/hymn/SE2002/671"
  },
  {
    "language": "polish",
    "number": 672,
    "title": "Gdy szedłem raz sam",
    "source_url": "https://hymnary.org/hymn/SE2002/672"
  },
  {
    "language": "polish",
    "number": 673,
    "title": "Gdy szukasz Boga, popatrz na kwiaty",
    "source_url": "https://hymnary.org/hymn/SE2002/673"
  },
  {
    "language": "polish",
    "number": 674,
    "title": "Gdzież mi pociechy",
    "source_url": "https://hymnary.org/hymn/SE2002/674"
  },
  {
    "language": "polish",
    "number": 675,
    "title": "Im większy krzyż, tym niebo bliżej",
    "source_url": "https://hymnary.org/hymn/SE2002/675"
  },
  {
    "language": "polish",
    "number": 676,
    "title": "Jako jeleń szuka zdroju",
    "source_url": "https://hymnary.org/hymn/SE2002/676"
  },
  {
    "language": "polish",
    "number": 677,
    "title": "Jezu, leźę u Twych nóg",
    "source_url": "https://hymnary.org/hymn/SE2002/677"
  },
  {
    "language": "polish",
    "number": 678,
    "title": "Jezu, zwycięstwo daj, Książę żywota",
    "source_url": "https://hymnary.org/hymn/SE2002/678"
  },
  {
    "language": "polish",
    "number": 679,
    "title": "Już się nie bój dłużej",
    "source_url": "https://hymnary.org/hymn/SE2002/679"
  },
  {
    "language": "polish",
    "number": 682,
    "title": "Zbyt dobrze wiem, kim jestem",
    "source_url": "https://hymnary.org/hymn/SE2002/682"
  },
  {
    "language": "polish",
    "number": 683,
    "title": "Mialem Jezusa, Zbawiciela swego",
    "source_url": "https://hymnary.org/hymn/SE2002/683"
  },
  {
    "language": "polish",
    "number": 684,
    "title": "Mów, Panie, do mnie w każdej życia chwili",
    "source_url": "https://hymnary.org/hymn/SE2002/684"
  },
  {
    "language": "polish",
    "number": 685,
    "title": "Na Bożą wolę zdaję się",
    "source_url": "https://hymnary.org/hymn/SE2002/685"
  },
  {
    "language": "polish",
    "number": 686,
    "title": "Nie bój się już",
    "source_url": "https://hymnary.org/hymn/SE2002/686"
  },
  {
    "language": "polish",
    "number": 688,
    "title": "Niech cię, chrzeṡcijaninie",
    "source_url": "https://hymnary.org/hymn/SE2002/688"
  },
  {
    "language": "polish",
    "number": 689,
    "title": "O Boże, z łaski swojej",
    "source_url": "https://hymnary.org/hymn/SE2002/689"
  },
  {
    "language": "polish",
    "number": 690,
    "title": "O Boże, znana dobroć Twa",
    "source_url": "https://hymnary.org/hymn/SE2002/690"
  },
  {
    "language": "polish",
    "number": 691,
    "title": "O, Panie, jako zechcesz sam",
    "source_url": "https://hymnary.org/hymn/SE2002/691"
  },
  {
    "language": "polish",
    "number": 692,
    "title": "O przyjaciel to nasz, Jezus",
    "source_url": "https://hymnary.org/hymn/SE2002/692"
  },
  {
    "language": "polish",
    "number": 693,
    "title": "Otwórz me oczy",
    "source_url": "https://hymnary.org/hymn/SE2002/693"
  },
  {
    "language": "polish",
    "number": 694,
    "title": "Pan Bóg jest mą silą",
    "source_url": "https://hymnary.org/hymn/SE2002/694"
  },
  {
    "language": "polish",
    "number": 695,
    "title": "Pan Bóg ma pieczę!",
    "source_url": "https://hymnary.org/hymn/SE2002/695"
  },
  {
    "language": "polish",
    "number": 696,
    "title": "Panie, Ty widzisz",
    "source_url": "https://hymnary.org/hymn/SE2002/696"
  },
  {
    "language": "polish",
    "number": 697,
    "title": "Polecaj drogi swoje",
    "source_url": "https://hymnary.org/hymn/SE2002/697"
  },
  {
    "language": "polish",
    "number": 698,
    "title": "Porzuć swe troski!",
    "source_url": "https://hymnary.org/hymn/SE2002/698"
  },
  {
    "language": "polish",
    "number": 699,
    "title": "Pozwól, duszo, Bogu rządzić",
    "source_url": "https://hymnary.org/hymn/SE2002/699"
  },
  {
    "language": "polish",
    "number": 700,
    "title": "Sam Pan Bóg raczy",
    "source_url": "https://hymnary.org/hymn/SE2002/700"
  },
  {
    "language": "polish",
    "number": 701,
    "title": "Siecią pokus omotani",
    "source_url": "https://hymnary.org/hymn/SE2002/701"
  },
  {
    "language": "polish",
    "number": 702,
    "title": "Tyś ucieczką moją Panie!",
    "source_url": "https://hymnary.org/hymn/SE2002/702"
  },
  {
    "language": "polish",
    "number": 703,
    "title": "Ufam Bogu w mym niszczęściu",
    "source_url": "https://hymnary.org/hymn/SE2002/703"
  },
  {
    "language": "polish",
    "number": 704,
    "title": "Uspokój się, o duszo miła",
    "source_url": "https://hymnary.org/hymn/SE2002/704"
  },
  {
    "language": "polish",
    "number": 705,
    "title": "W Bogu pokladam",
    "source_url": "https://hymnary.org/hymn/SE2002/705"
  },
  {
    "language": "polish",
    "number": 706,
    "title": "W uciskach, w krzyżu",
    "source_url": "https://hymnary.org/hymn/SE2002/706"
  },
  {
    "language": "polish",
    "number": 707,
    "title": "W mych wszystkich sprawach, Panie",
    "source_url": "https://hymnary.org/hymn/SE2002/707"
  },
  {
    "language": "polish",
    "number": 708,
    "title": "W ucisku moim",
    "source_url": "https://hymnary.org/hymn/SE2002/708"
  },
  {
    "language": "polish",
    "number": 709,
    "title": "We dnie i w nocy",
    "source_url": "https://hymnary.org/hymn/SE2002/709"
  },
  {
    "language": "polish",
    "number": 710,
    "title": "Woli Pańskiej się paddaję",
    "source_url": "https://hymnary.org/hymn/SE2002/710"
  },
  {
    "language": "polish",
    "number": 711,
    "title": "Wszyscy, co składają",
    "source_url": "https://hymnary.org/hymn/SE2002/711"
  },
  {
    "language": "polish",
    "number": 712,
    "title": "Z milości jest, co czyni Bóg",
    "source_url": "https://hymnary.org/hymn/SE2002/712"
  },
  {
    "language": "polish",
    "number": 713,
    "title": "Za rękę weź mnie, Panie",
    "source_url": "https://hymnary.org/hymn/SE2002/713"
  },
  {
    "language": "polish",
    "number": 714,
    "title": "Źle nie postąpisz z nami",
    "source_url": "https://hymnary.org/hymn/SE2002/714"
  },
  {
    "language": "polish",
    "number": 715,
    "title": "Ach, potrzebuję Cię",
    "source_url": "https://hymnary.org/hymn/SE2002/715"
  },
  {
    "language": "polish",
    "number": 716,
    "title": "Ach, ześlij, Panie, przebudzenie",
    "source_url": "https://hymnary.org/hymn/SE2002/716"
  },
  {
    "language": "polish",
    "number": 717,
    "title": "Bądź gotowy, duchu mój",
    "source_url": "https://hymnary.org/hymn/SE2002/717"
  },
  {
    "language": "polish",
    "number": 718,
    "title": "By być jak Jezus",
    "source_url": "https://hymnary.org/hymn/SE2002/718"
  },
  {
    "language": "polish",
    "number": 719,
    "title": "Chcemy do śmierci Jezusie być Twoi",
    "source_url": "https://hymnary.org/hymn/SE2002/719"
  },
  {
    "language": "polish",
    "number": 720,
    "title": "Chyrste, Ty Wodzu mej wiary",
    "source_url": "https://hymnary.org/hymn/SE2002/720"
  },
  {
    "language": "polish",
    "number": 721,
    "title": "Chrześcijaninie, zbudź się, wstań",
    "source_url": "https://hymnary.org/hymn/SE2002/721"
  },
  {
    "language": "polish",
    "number": 722,
    "title": "Ciebie tylko, Jezu drogi",
    "source_url": "https://hymnary.org/hymn/SE2002/722"
  },
  {
    "language": "polish",
    "number": 723,
    "title": "Czyli nie masz dla Jezusa",
    "source_url": "https://hymnary.org/hymn/SE2002/723"
  },
  {
    "language": "polish",
    "number": 724,
    "title": "Czymżeśmy bez Ciebie, Jezu",
    "source_url": "https://hymnary.org/hymn/SE2002/724"
  },
  {
    "language": "polish",
    "number": 725,
    "title": "Daj, Boże, bym pamiętal",
    "source_url": "https://hymnary.org/hymn/SE2002/725"
  },
  {
    "language": "polish",
    "number": 726,
    "title": "Gdy patrzę na cudowny krzyż",
    "source_url": "https://hymnary.org/hymn/SE2002/726"
  },
  {
    "language": "polish",
    "number": 727,
    "title": "Ja chcę, o Boże, wolę Twoją czynić",
    "source_url": "https://hymnary.org/hymn/SE2002/727"
  },
  {
    "language": "polish",
    "number": 728,
    "title": "Jak jestem, idę całkiem tak",
    "source_url": "https://hymnary.org/hymn/SE2002/728"
  },
  {
    "language": "polish",
    "number": 729,
    "title": "Jakżebym chciał, o Boże",
    "source_url": "https://hymnary.org/hymn/SE2002/729"
  },
  {
    "language": "polish",
    "number": 730,
    "title": "Kim jestem? Ważne to pytanie",
    "source_url": "https://hymnary.org/hymn/SE2002/730"
  },
  {
    "language": "polish",
    "number": 731,
    "title": "Kto z Chrystusem nie chodził",
    "source_url": "https://hymnary.org/hymn/SE2002/731"
  },
  {
    "language": "polish",
    "number": 732,
    "title": "Ku niebiosom dążmy wciąż",
    "source_url": "https://hymnary.org/hymn/SE2002/732"
  },
  {
    "language": "polish",
    "number": 733,
    "title": "Mą wiarą patrzę wzwyż",
    "source_url": "https://hymnary.org/hymn/SE2002/733"
  },
  {
    "language": "polish",
    "number": 734,
    "title": "Mój Boże, jako chcesz",
    "source_url": "https://hymnary.org/hymn/SE2002/734"
  },
  {
    "language": "polish",
    "number": 736,
    "title": "Nie mam nic, co bym mógł Tobie dać",
    "source_url": "https://hymnary.org/hymn/SE2002/736"
  },
  {
    "language": "polish",
    "number": 737,
    "title": "Nie omijaj mnie, o Zbawco",
    "source_url": "https://hymnary.org/hymn/SE2002/737"
  },
  {
    "language": "polish",
    "number": 738,
    "title": "Nie źaluję, nie żałuję",
    "source_url": "https://hymnary.org/hymn/SE2002/738"
  },
  {
    "language": "polish",
    "number": 739,
    "title": "Nikt nie może panom dwom",
    "source_url": "https://hymnary.org/hymn/SE2002/739"
  },
  {
    "language": "polish",
    "number": 740,
    "title": "O duszo ma",
    "source_url": "https://hymnary.org/hymn/SE2002/740"
  },
  {
    "language": "polish",
    "number": 741,
    "title": "O duszo, powstań z gronem",
    "source_url": "https://hymnary.org/hymn/SE2002/741"
  },
  {
    "language": "polish",
    "number": 742,
    "title": "O, potrzeba mi jednego",
    "source_url": "https://hymnary.org/hymn/SE2002/742"
  },
  {
    "language": "polish",
    "number": 743,
    "title": "Ojcze, być podobnym Tobie",
    "source_url": "https://hymnary.org/hymn/SE2002/743"
  },
  {
    "language": "polish",
    "number": 744,
    "title": "On szedł w spiekocie dnia",
    "source_url": "https://hymnary.org/hymn/SE2002/744"
  },
  {
    "language": "polish",
    "number": 745,
    "title": "Otwórzcie serca, żyć będziecie!",
    "source_url": "https://hymnary.org/hymn/SE2002/745"
  },
  {
    "language": "polish",
    "number": 746,
    "title": "Pan kiedyś stanął nad brzegiem",
    "source_url": "https://hymnary.org/hymn/SE2002/746"
  },
  {
    "language": "polish",
    "number": 747,
    "title": "Panie mój, przychodzę dziś",
    "source_url": "https://hymnary.org/hymn/SE2002/747"
  },
  {
    "language": "polish",
    "number": 748,
    "title": "Po dwóch drogach spieszy mnogi lud",
    "source_url": "https://hymnary.org/hymn/SE2002/748"
  },
  {
    "language": "polish",
    "number": 749,
    "title": "Posłuchajcie wierni, Pana",
    "source_url": "https://hymnary.org/hymn/SE2002/749"
  },
  {
    "language": "polish",
    "number": 750,
    "title": "Pójdę za Jezusem!",
    "source_url": "https://hymnary.org/hymn/SE2002/750"
  },
  {
    "language": "polish",
    "number": 751,
    "title": "Pójdź do Jezusa, dziś jeszcze czas!",
    "source_url": "https://hymnary.org/hymn/SE2002/751"
  },
  {
    "language": "polish",
    "number": 752,
    "title": "Przybądź do mnie, Jezu Panie",
    "source_url": "https://hymnary.org/hymn/SE2002/752"
  },
  {
    "language": "polish",
    "number": 753,
    "title": "Przyjacielu, z nami pójdź w górny kraj",
    "source_url": "https://hymnary.org/hymn/SE2002/753"
  },
  {
    "language": "polish",
    "number": 754,
    "title": "Rzuć, człowiecze, marny świat",
    "source_url": "https://hymnary.org/hymn/SE2002/754"
  },
  {
    "language": "polish",
    "number": 755,
    "title": "Serce czyste stwórz mi, Panie",
    "source_url": "https://hymnary.org/hymn/SE2002/755"
  },
  {
    "language": "polish",
    "number": 756,
    "title": "Spojrzyj na Jezusa, duszo, pospiesz doń!",
    "source_url": "https://hymnary.org/hymn/SE2002/756"
  },
  {
    "language": "polish",
    "number": 757,
    "title": "Stwórz serce czyste we mnie",
    "source_url": "https://hymnary.org/hymn/SE2002/757"
  },
  {
    "language": "polish",
    "number": 758,
    "title": "Toruj, Jezu, sam",
    "source_url": "https://hymnary.org/hymn/SE2002/758"
  },
  {
    "language": "polish",
    "number": 759,
    "title": "Tu serce me!",
    "source_url": "https://hymnary.org/hymn/SE2002/759"
  },
  {
    "language": "polish",
    "number": 760,
    "title": "Uczyń mnie sługą pokornym już dziś",
    "source_url": "https://hymnary.org/hymn/SE2002/760"
  },
  {
    "language": "polish",
    "number": 761,
    "title": "Ujmij mą dłon",
    "source_url": "https://hymnary.org/hymn/SE2002/761"
  },
  {
    "language": "polish",
    "number": 762,
    "title": "Umierać z Panem, dła Niego żyć",
    "source_url": "https://hymnary.org/hymn/SE2002/762"
  },
  {
    "language": "polish",
    "number": 763,
    "title": "W krag, przez cały świat",
    "source_url": "https://hymnary.org/hymn/SE2002/763"
  },
  {
    "language": "polish",
    "number": 764,
    "title": "W śład za Mną! Wola Chrystus Pan",
    "source_url": "https://hymnary.org/hymn/SE2002/764"
  },
  {
    "language": "polish",
    "number": 765,
    "title": "Weź, Jezusie, życie me",
    "source_url": "https://hymnary.org/hymn/SE2002/765"
  },
  {
    "language": "polish",
    "number": 766,
    "title": "Wędrowcze, wróć do Ojca, wróć",
    "source_url": "https://hymnary.org/hymn/SE2002/766"
  },
  {
    "language": "polish",
    "number": 767,
    "title": "Wiele lat błądziłem w świecie sam",
    "source_url": "https://hymnary.org/hymn/SE2002/767"
  },
  {
    "language": "polish",
    "number": 768,
    "title": "Wiernym bądź",
    "source_url": "https://hymnary.org/hymn/SE2002/768"
  },
  {
    "language": "polish",
    "number": 769,
    "title": "Wszystko Tobie dziś oddaje",
    "source_url": "https://hymnary.org/hymn/SE2002/769"
  },
  {
    "language": "polish",
    "number": 770,
    "title": "Wybrać mi kazano skarb",
    "source_url": "https://hymnary.org/hymn/SE2002/770"
  },
  {
    "language": "polish",
    "number": 771,
    "title": "Wyźej, ma duszo, wskazanym ci torem!",
    "source_url": "https://hymnary.org/hymn/SE2002/771"
  },
  {
    "language": "polish",
    "number": 772,
    "title": "Z radością skieruj w górę wzrok",
    "source_url": "https://hymnary.org/hymn/SE2002/772"
  },
  {
    "language": "polish",
    "number": 773,
    "title": "Za Jezusem chętnie powędruję",
    "source_url": "https://hymnary.org/hymn/SE2002/773"
  },
  {
    "language": "polish",
    "number": 774,
    "title": "Za Jezusem podążajmy",
    "source_url": "https://hymnary.org/hymn/SE2002/774"
  },
  {
    "language": "polish",
    "number": 775,
    "title": "Zaufaj nowej drodze",
    "source_url": "https://hymnary.org/hymn/SE2002/775"
  },
  {
    "language": "polish",
    "number": 776,
    "title": "Znów powracam w progi Twoje",
    "source_url": "https://hymnary.org/hymn/SE2002/776"
  },
  {
    "language": "polish",
    "number": 777,
    "title": "Wyjdż jej tylko naprzeciw",
    "source_url": "https://hymnary.org/hymn/SE2002/777"
  },
  {
    "language": "polish",
    "number": 778,
    "title": "Bóg jest miłością On mnie odkupil!",
    "source_url": "https://hymnary.org/hymn/SE2002/778"
  },
  {
    "language": "polish",
    "number": 779,
    "title": "Bóg kocha ciebie i mnie",
    "source_url": "https://hymnary.org/hymn/SE2002/779"
  },
  {
    "language": "polish",
    "number": 780,
    "title": "Caly świat jest pelen Twej milości",
    "source_url": "https://hymnary.org/hymn/SE2002/780"
  },
  {
    "language": "polish",
    "number": 781,
    "title": "Chcę kochać Ciebie, Boży Synu",
    "source_url": "https://hymnary.org/hymn/SE2002/781"
  },
  {
    "language": "polish",
    "number": 782,
    "title": "Chcę przy tobie zostać, Panie",
    "source_url": "https://hymnary.org/hymn/SE2002/782"
  },
  {
    "language": "polish",
    "number": 783,
    "title": "Ducha milości",
    "source_url": "https://hymnary.org/hymn/SE2002/783"
  },
  {
    "language": "polish",
    "number": 784,
    "title": "Gdybym Cię nie mial Jezu mój kochany",
    "source_url": "https://hymnary.org/hymn/SE2002/784"
  },
  {
    "language": "polish",
    "number": 785,
    "title": "Gwiazdą w mych cięmnościach",
    "source_url": "https://hymnary.org/hymn/SE2002/785"
  },
  {
    "language": "polish",
    "number": 786,
    "title": "Idż, osusz łzy swoje",
    "source_url": "https://hymnary.org/hymn/SE2002/786"
  },
  {
    "language": "polish",
    "number": 787,
    "title": "Imię Jezus wiecz nie żywe",
    "source_url": "https://hymnary.org/hymn/SE2002/787"
  },
  {
    "language": "polish",
    "number": 788,
    "title": "Przez wody mórz Jezus, mój stróż",
    "source_url": "https://hymnary.org/hymn/SE2002/788"
  },
  {
    "language": "polish",
    "number": 789,
    "title": "Jam Twą własnością!",
    "source_url": "https://hymnary.org/hymn/SE2002/789"
  },
  {
    "language": "polish",
    "number": 790,
    "title": "Jaśniejąca chwało",
    "source_url": "https://hymnary.org/hymn/SE2002/790"
  },
  {
    "language": "polish",
    "number": 791,
    "title": "Jaṡnieje wewnętrzne u chrześcijan życie",
    "source_url": "https://hymnary.org/hymn/SE2002/791"
  },
  {
    "language": "polish",
    "number": 792,
    "title": "Jezu, dobry dusz Pasterzu",
    "source_url": "https://hymnary.org/hymn/SE2002/792"
  },
  {
    "language": "polish",
    "number": 794,
    "title": "Jezu, któż jak Ty",
    "source_url": "https://hymnary.org/hymn/SE2002/794"
  },
  {
    "language": "polish",
    "number": 795,
    "title": "Jezu, ma radości",
    "source_url": "https://hymnary.org/hymn/SE2002/795"
  },
  {
    "language": "polish",
    "number": 797,
    "title": "Jezu, o tarczo walczących",
    "source_url": "https://hymnary.org/hymn/SE2002/797"
  },
  {
    "language": "polish",
    "number": 798,
    "title": "Jezu, prawdziwa światłości",
    "source_url": "https://hymnary.org/hymn/SE2002/798"
  },
  {
    "language": "polish",
    "number": 800,
    "title": "Jezu, w Tobie życia chleb",
    "source_url": "https://hymnary.org/hymn/SE2002/800"
  },
  {
    "language": "polish",
    "number": 801,
    "title": "Jezu, Zbawco mojej duszy",
    "source_url": "https://hymnary.org/hymn/SE2002/801"
  },
  {
    "language": "polish",
    "number": 802,
    "title": "Królu mój, Królu chwaly",
    "source_url": "https://hymnary.org/hymn/SE2002/802"
  },
  {
    "language": "polish",
    "number": 803,
    "title": "Mają ptaki gniazda swoje",
    "source_url": "https://hymnary.org/hymn/SE2002/803"
  },
  {
    "language": "polish",
    "number": 804,
    "title": "Miałem Jezusa",
    "source_url": "https://hymnary.org/hymn/SE2002/804"
  },
  {
    "language": "polish",
    "number": 805,
    "title": "Miloṡć posłała Jezusa na śmierć",
    "source_url": "https://hymnary.org/hymn/SE2002/805"
  },
  {
    "language": "polish",
    "number": 806,
    "title": "Nad wszystko pożądany",
    "source_url": "https://hymnary.org/hymn/SE2002/806"
  },
  {
    "language": "polish",
    "number": 807,
    "title": "O Chryste, w sercu moim",
    "source_url": "https://hymnary.org/hymn/SE2002/807"
  },
  {
    "language": "polish",
    "number": 808,
    "title": "O czasom niepodlegly",
    "source_url": "https://hymnary.org/hymn/SE2002/808"
  },
  {
    "language": "polish",
    "number": 809,
    "title": "O Jezu, słońce łaski",
    "source_url": "https://hymnary.org/hymn/SE2002/809"
  },
  {
    "language": "polish",
    "number": 810,
    "title": "O Jezusie, zbaw mą duszę",
    "source_url": "https://hymnary.org/hymn/SE2002/810"
  },
  {
    "language": "polish",
    "number": 811,
    "title": "O Milości, coś raczyła",
    "source_url": "https://hymnary.org/hymn/SE2002/811"
  },
  {
    "language": "polish",
    "number": 812,
    "title": "O mily Jezu",
    "source_url": "https://hymnary.org/hymn/SE2002/812"
  },
  {
    "language": "polish",
    "number": 813,
    "title": "O najmilszy Zbawicielu",
    "source_url": "https://hymnary.org/hymn/SE2002/813"
  },
  {
    "language": "polish",
    "number": 814,
    "title": "Pan jest Pasterzem moim",
    "source_url": "https://hymnary.org/hymn/SE2002/814"
  },
  {
    "language": "polish",
    "number": 815,
    "title": "Panie, co mieszkasz",
    "source_url": "https://hymnary.org/hymn/SE2002/815"
  },
  {
    "language": "polish",
    "number": 816,
    "title": "Przyjaciela mam, co pociesza mnie",
    "source_url": "https://hymnary.org/hymn/SE2002/816"
  },
  {
    "language": "polish",
    "number": 817,
    "title": "Radość jest w Tobie w cierpienia dobie",
    "source_url": "https://hymnary.org/hymn/SE2002/817"
  },
  {
    "language": "polish",
    "number": 818,
    "title": "Swój wierny obraz, Panie",
    "source_url": "https://hymnary.org/hymn/SE2002/818"
  },
  {
    "language": "polish",
    "number": 819,
    "title": "Uwielbiam moc milości świętą",
    "source_url": "https://hymnary.org/hymn/SE2002/819"
  },
  {
    "language": "polish",
    "number": 820,
    "title": "W Tobie, Chryste Panie",
    "source_url": "https://hymnary.org/hymn/SE2002/820"
  },
  {
    "language": "polish",
    "number": 821,
    "title": "Z nieba idę na ten ṡwiat",
    "source_url": "https://hymnary.org/hymn/SE2002/821"
  },
  {
    "language": "polish",
    "number": 822,
    "title": "Będziesz miłował Boga całym",
    "source_url": "https://hymnary.org/hymn/SE2002/822"
  },
  {
    "language": "polish",
    "number": 823,
    "title": "Chodż prostą drogą",
    "source_url": "https://hymnary.org/hymn/SE2002/823"
  },
  {
    "language": "polish",
    "number": 825,
    "title": "Kto mówi: \"Boga ja miłuję\"",
    "source_url": "https://hymnary.org/hymn/SE2002/825"
  },
  {
    "language": "polish",
    "number": 826,
    "title": "Litościwy Jezu nasz",
    "source_url": "https://hymnary.org/hymn/SE2002/826"
  },
  {
    "language": "polish",
    "number": 827,
    "title": "Miłosiernym bądź dla brata",
    "source_url": "https://hymnary.org/hymn/SE2002/827"
  },
  {
    "language": "polish",
    "number": 828,
    "title": "Miłość Bożą w sercu swym dzisiaj mam",
    "source_url": "https://hymnary.org/hymn/SE2002/828"
  },
  {
    "language": "polish",
    "number": 829,
    "title": "Miłość czynem jest",
    "source_url": "https://hymnary.org/hymn/SE2002/829"
  },
  {
    "language": "polish",
    "number": 830,
    "title": "Miłuj! Tak Zbawca",
    "source_url": "https://hymnary.org/hymn/SE2002/830"
  },
  {
    "language": "polish",
    "number": 831,
    "title": "Pomóż mi, Jezu",
    "source_url": "https://hymnary.org/hymn/SE2002/831"
  },
  {
    "language": "polish",
    "number": 832,
    "title": "Pomóż, Panie źycia",
    "source_url": "https://hymnary.org/hymn/SE2002/832"
  },
  {
    "language": "polish",
    "number": 833,
    "title": "To przykazanie Ja dziś daję wam",
    "source_url": "https://hymnary.org/hymn/SE2002/833"
  },
  {
    "language": "polish",
    "number": 834,
    "title": "Twój jest ṡwiat, twymi brachmi są",
    "source_url": "https://hymnary.org/hymn/SE2002/834"
  },
  {
    "language": "polish",
    "number": 835,
    "title": "Ubi caritas et amor",
    "source_url": "https://hymnary.org/hymn/SE2002/835"
  },
  {
    "language": "polish",
    "number": 836,
    "title": "Warto dła jednej milości żyć",
    "source_url": "https://hymnary.org/hymn/SE2002/836"
  },
  {
    "language": "polish",
    "number": 837,
    "title": "Boże, coṡ Polskę przez tak liczne wieki",
    "source_url": "https://hymnary.org/hymn/SE2002/837"
  },
  {
    "language": "polish",
    "number": 838,
    "title": "Bóg jeden jest, On wiecznie trwa",
    "source_url": "https://hymnary.org/hymn/SE2002/838"
  },
  {
    "language": "polish",
    "number": 839,
    "title": "Bóg jest wielki w dziełach swoich",
    "source_url": "https://hymnary.org/hymn/SE2002/839"
  },
  {
    "language": "polish",
    "number": 840,
    "title": "Chwalimy, Boże, Cię",
    "source_url": "https://hymnary.org/hymn/SE2002/840"
  },
  {
    "language": "polish",
    "number": 841,
    "title": "Ciągły niepokój na ṡwiecie",
    "source_url": "https://hymnary.org/hymn/SE2002/841"
  },
  {
    "language": "polish",
    "number": 842,
    "title": "Daj pokój nam, o Panie",
    "source_url": "https://hymnary.org/hymn/SE2002/842"
  },
  {
    "language": "polish",
    "number": 843,
    "title": "Dajże pokój w każdy dzień",
    "source_url": "https://hymnary.org/hymn/SE2002/843"
  },
  {
    "language": "polish",
    "number": 844,
    "title": "Dona nobis pacem pacem",
    "source_url": "https://hymnary.org/hymn/SE2002/844"
  },
  {
    "language": "polish",
    "number": 845,
    "title": "Gdy idziemy poprzez świat, chwalmy Boga",
    "source_url": "https://hymnary.org/hymn/SE2002/845"
  },
  {
    "language": "polish",
    "number": 846,
    "title": "Gdy na ten świat spoglądam wielki Boże",
    "source_url": "https://hymnary.org/hymn/SE2002/846"
  },
  {
    "language": "polish",
    "number": 847,
    "title": "Gdy zacznę zastanawiać się",
    "source_url": "https://hymnary.org/hymn/SE2002/847"
  },
  {
    "language": "polish",
    "number": 848,
    "title": "Gdzie zwrócę oko swoje",
    "source_url": "https://hymnary.org/hymn/SE2002/848"
  },
  {
    "language": "polish",
    "number": 849,
    "title": "Gdziekolwiek sięgnie wzrok",
    "source_url": "https://hymnary.org/hymn/SE2002/849"
  },
  {
    "language": "polish",
    "number": 850,
    "title": "Hevenu shalom alechem",
    "source_url": "https://hymnary.org/hymn/SE2002/850"
  },
  {
    "language": "polish",
    "number": 851,
    "title": "Kiedy patrzysz w nocne niebo, jasność bije zeń",
    "source_url": "https://hymnary.org/hymn/SE2002/851"
  },
  {
    "language": "polish",
    "number": 852,
    "title": "Królu niebios! Któż imienia Twego zgłębi treść",
    "source_url": "https://hymnary.org/hymn/SE2002/852"
  },
  {
    "language": "polish",
    "number": 853,
    "title": "Królu wysokiego nieba",
    "source_url": "https://hymnary.org/hymn/SE2002/853"
  },
  {
    "language": "polish",
    "number": 854,
    "title": "Na wszystkich drogach, Panie",
    "source_url": "https://hymnary.org/hymn/SE2002/854"
  },
  {
    "language": "polish",
    "number": 855,
    "title": "O Boże, łaska Twa",
    "source_url": "https://hymnary.org/hymn/SE2002/855"
  },
  {
    "language": "polish",
    "number": 856,
    "title": "O Boże, usłysz głos prośby naszej",
    "source_url": "https://hymnary.org/hymn/SE2002/856"
  },
  {
    "language": "polish",
    "number": 857,
    "title": "O dobry Boże, życia drogi",
    "source_url": "https://hymnary.org/hymn/SE2002/857"
  },
  {
    "language": "polish",
    "number": 858,
    "title": "Pan nasz króluje",
    "source_url": "https://hymnary.org/hymn/SE2002/858"
  },
  {
    "language": "polish",
    "number": 859,
    "title": "Pasterzu ludów, Wodzu nasz",
    "source_url": "https://hymnary.org/hymn/SE2002/859"
  },
  {
    "language": "polish",
    "number": 860,
    "title": "Pokuju udziel z łaski nam",
    "source_url": "https://hymnary.org/hymn/SE2002/860"
  },
  {
    "language": "polish",
    "number": 861,
    "title": "Słysz, Panie, möj glos",
    "source_url": "https://hymnary.org/hymn/SE2002/861"
  },
  {
    "language": "polish",
    "number": 862,
    "title": "Szalom Szaverim",
    "source_url": "https://hymnary.org/hymn/SE2002/862"
  },
  {
    "language": "polish",
    "number": 863,
    "title": "Wspaniały ṡwiat, prawdziwy raj",
    "source_url": "https://hymnary.org/hymn/SE2002/863"
  },
  {
    "language": "polish",
    "number": 864,
    "title": "Wszechmocny Panie",
    "source_url": "https://hymnary.org/hymn/SE2002/864"
  },
  {
    "language": "polish",
    "number": 865,
    "title": "Wszyscy, co po ziemi tu chodzicie",
    "source_url": "https://hymnary.org/hymn/SE2002/865"
  },
  {
    "language": "polish",
    "number": 866,
    "title": "Cześć, jaką Ci składamy",
    "source_url": "https://hymnary.org/hymn/SE2002/866"
  },
  {
    "language": "polish",
    "number": 867,
    "title": "Gdy co dzień zniżam się w głąb ziemi",
    "source_url": "https://hymnary.org/hymn/SE2002/867"
  },
  {
    "language": "polish",
    "number": 868,
    "title": "Gdy kończymy prace swe",
    "source_url": "https://hymnary.org/hymn/SE2002/868"
  },
  {
    "language": "polish",
    "number": 869,
    "title": "Mą drogę znasz, choć ja jej nie znam wcale",
    "source_url": "https://hymnary.org/hymn/SE2002/869"
  },
  {
    "language": "polish",
    "number": 870,
    "title": "Mój Pan drogę zna przez największy gąszcz",
    "source_url": "https://hymnary.org/hymn/SE2002/870"
  },
  {
    "language": "polish",
    "number": 871,
    "title": "Nie opuṡć, Boźe, mnie",
    "source_url": "https://hymnary.org/hymn/SE2002/871"
  },
  {
    "language": "polish",
    "number": 872,
    "title": "Nim wyszedłeś dzisiaj z domu",
    "source_url": "https://hymnary.org/hymn/SE2002/872"
  },
  {
    "language": "polish",
    "number": 874,
    "title": "O przenajświętszy",
    "source_url": "https://hymnary.org/hymn/SE2002/874"
  },
  {
    "language": "polish",
    "number": 875,
    "title": "Panie, w moc Twoją ufamy",
    "source_url": "https://hymnary.org/hymn/SE2002/875"
  },
  {
    "language": "polish",
    "number": 876,
    "title": "Pośrod wszystkich życia trosk i klopotów",
    "source_url": "https://hymnary.org/hymn/SE2002/876"
  },
  {
    "language": "polish",
    "number": 877,
    "title": "Przedwieczny Boże nasz",
    "source_url": "https://hymnary.org/hymn/SE2002/877"
  },
  {
    "language": "polish",
    "number": 878,
    "title": "Różnymi dary",
    "source_url": "https://hymnary.org/hymn/SE2002/878"
  },
  {
    "language": "polish",
    "number": 879,
    "title": "\"Szczęść Boże!\"— tak wolamy",
    "source_url": "https://hymnary.org/hymn/SE2002/879"
  },
  {
    "language": "polish",
    "number": 880,
    "title": "W drogę z nami wyrusz, Panie",
    "source_url": "https://hymnary.org/hymn/SE2002/880"
  },
  {
    "language": "polish",
    "number": 881,
    "title": "W Pańskim imieniu w grogę się undaję",
    "source_url": "https://hymnary.org/hymn/SE2002/881"
  },
  {
    "language": "polish",
    "number": 882,
    "title": "W światlości nieprzystępnej",
    "source_url": "https://hymnary.org/hymn/SE2002/882"
  },
  {
    "language": "polish",
    "number": 883,
    "title": "W ziemskim mym istnieniu",
    "source_url": "https://hymnary.org/hymn/SE2002/883"
  },
  {
    "language": "polish",
    "number": 884,
    "title": "Z Bogiem bądźcie, aż się zejdziem znów!",
    "source_url": "https://hymnary.org/hymn/SE2002/884"
  },
  {
    "language": "polish",
    "number": 885,
    "title": "Z Bogiem, z Bogiem każda sprawa!",
    "source_url": "https://hymnary.org/hymn/SE2002/885"
  },
  {
    "language": "polish",
    "number": 886,
    "title": "Zdarz, bym we wszystkich sprawach swych o Panie",
    "source_url": "https://hymnary.org/hymn/SE2002/886"
  },
  {
    "language": "polish",
    "number": 887,
    "title": "Boźe, moc Twa opartruje",
    "source_url": "https://hymnary.org/hymn/SE2002/887"
  },
  {
    "language": "polish",
    "number": 888,
    "title": "Boże stworzenia zlączcie się!",
    "source_url": "https://hymnary.org/hymn/SE2002/888"
  },
  {
    "language": "polish",
    "number": 889,
    "title": "Chwała Bogu, który daje",
    "source_url": "https://hymnary.org/hymn/SE2002/889"
  },
  {
    "language": "polish",
    "number": 890,
    "title": "Ciebie, Boże, lud Twój wzywa",
    "source_url": "https://hymnary.org/hymn/SE2002/890"
  },
  {
    "language": "polish",
    "number": 891,
    "title": "Do Ciebie wolam, Boże mój",
    "source_url": "https://hymnary.org/hymn/SE2002/891"
  },
  {
    "language": "polish",
    "number": 892,
    "title": "Dosyć, Boże, deszecze lały",
    "source_url": "https://hymnary.org/hymn/SE2002/892"
  },
  {
    "language": "polish",
    "number": 893,
    "title": "Jesień nadeszła",
    "source_url": "https://hymnary.org/hymn/SE2002/893"
  },
  {
    "language": "polish",
    "number": 894,
    "title": "Jesteś Panem stworzenia i Panem mych dni",
    "source_url": "https://hymnary.org/hymn/SE2002/894"
  },
  {
    "language": "polish",
    "number": 895,
    "title": "O Boże, wspomnij",
    "source_url": "https://hymnary.org/hymn/SE2002/895"
  },
  {
    "language": "polish",
    "number": 896,
    "title": "Panie, wszystko Twe stworzenie",
    "source_url": "https://hymnary.org/hymn/SE2002/896"
  },
  {
    "language": "polish",
    "number": 897,
    "title": "Pola już białe, kosy się kłaniają",
    "source_url": "https://hymnary.org/hymn/SE2002/897"
  },
  {
    "language": "polish",
    "number": 898,
    "title": "Wiesz ty, ile gwiazdek świeci",
    "source_url": "https://hymnary.org/hymn/SE2002/898"
  },
  {
    "language": "polish",
    "number": 899,
    "title": "Zaśpiewaj pieśni, serce me",
    "source_url": "https://hymnary.org/hymn/SE2002/899"
  },
  {
    "language": "polish",
    "number": 900,
    "title": "Ziemia śmierci snem zasnęła",
    "source_url": "https://hymnary.org/hymn/SE2002/900"
  },
  {
    "language": "polish",
    "number": 901,
    "title": "Ach, jak marny, jak nietrwały",
    "source_url": "https://hymnary.org/hymn/SE2002/901"
  },
  {
    "language": "polish",
    "number": 902,
    "title": "Ach, jakie gorzki żale",
    "source_url": "https://hymnary.org/hymn/SE2002/902"
  },
  {
    "language": "polish",
    "number": 903,
    "title": "Do nieba, serce moje",
    "source_url": "https://hymnary.org/hymn/SE2002/903"
  },
  {
    "language": "polish",
    "number": 904,
    "title": "Do widzenia w onym lepszym kraju",
    "source_url": "https://hymnary.org/hymn/SE2002/904"
  },
  {
    "language": "polish",
    "number": 905,
    "title": "Dość mam, dosyć tego świata",
    "source_url": "https://hymnary.org/hymn/SE2002/905"
  },
  {
    "language": "polish",
    "number": 906,
    "title": "Dziś jeszeze żyję",
    "source_url": "https://hymnary.org/hymn/SE2002/906"
  },
  {
    "language": "polish",
    "number": 907,
    "title": "Stanę przed Stwórcą i przed moim Bogiem",
    "source_url": "https://hymnary.org/hymn/SE2002/907"
  },
  {
    "language": "polish",
    "number": 908,
    "title": "Gdy chwila juź nadejdzie ma",
    "source_url": "https://hymnary.org/hymn/SE2002/908"
  },
  {
    "language": "polish",
    "number": 909,
    "title": "Gdy dzieci z doczeności",
    "source_url": "https://hymnary.org/hymn/SE2002/909"
  },
  {
    "language": "polish",
    "number": 910,
    "title": "Gdzie duszy ojczyna",
    "source_url": "https://hymnary.org/hymn/SE2002/910"
  },
  {
    "language": "polish",
    "number": 911,
    "title": "Gdzieź serce, gdzie ojczyna ma?",
    "source_url": "https://hymnary.org/hymn/SE2002/911"
  },
  {
    "language": "polish",
    "number": 912,
    "title": "Jak będzie nam gdy po skończonym boju",
    "source_url": "https://hymnary.org/hymn/SE2002/912"
  },
  {
    "language": "polish",
    "number": 913,
    "title": "Jam gościem na tym ṡwiecie",
    "source_url": "https://hymnary.org/hymn/SE2002/913"
  },
  {
    "language": "polish",
    "number": 914,
    "title": "Jam stęskniony, jam stęskniony",
    "source_url": "https://hymnary.org/hymn/SE2002/914"
  },
  {
    "language": "polish",
    "number": 915,
    "title": "Jest pokój wieczny",
    "source_url": "https://hymnary.org/hymn/SE2002/915"
  },
  {
    "language": "polish",
    "number": 916,
    "title": "Jezus Chrystus, ufnoṡć ma",
    "source_url": "https://hymnary.org/hymn/SE2002/916"
  },
  {
    "language": "polish",
    "number": 917,
    "title": "Juź się wykonalo",
    "source_url": "https://hymnary.org/hymn/SE2002/917"
  },
  {
    "language": "polish",
    "number": 918,
    "title": "Już z tobą się rozstaję",
    "source_url": "https://hymnary.org/hymn/SE2002/918"
  },
  {
    "language": "polish",
    "number": 919,
    "title": "Kto wie, jak blisko me skonanie?",
    "source_url": "https://hymnary.org/hymn/SE2002/919"
  },
  {
    "language": "polish",
    "number": 920,
    "title": "Matczyne serce",
    "source_url": "https://hymnary.org/hymn/SE2002/920"
  },
  {
    "language": "polish",
    "number": 921,
    "title": "Mój Boże, wiem, że umrzeć muszę",
    "source_url": "https://hymnary.org/hymn/SE2002/921"
  },
  {
    "language": "polish",
    "number": 922,
    "title": "Naucz mnie obliczać, Panie",
    "source_url": "https://hymnary.org/hymn/SE2002/922"
  },
  {
    "language": "polish",
    "number": 923,
    "title": "Niech aniołowie",
    "source_url": "https://hymnary.org/hymn/SE2002/923"
  },
  {
    "language": "polish",
    "number": 924,
    "title": "O, jakeście wy błogosławieni",
    "source_url": "https://hymnary.org/hymn/SE2002/924"
  },
  {
    "language": "polish",
    "number": 925,
    "title": "O jakże ci szczęṡliwi są",
    "source_url": "https://hymnary.org/hymn/SE2002/925"
  },
  {
    "language": "polish",
    "number": 926,
    "title": "O Jezu, tyś ṡwiatłością mi",
    "source_url": "https://hymnary.org/hymn/SE2002/926"
  },
  {
    "language": "polish",
    "number": 927,
    "title": "O pielgrzymie, dokąd ṡpieszysz",
    "source_url": "https://hymnary.org/hymn/SE2002/927"
  },
  {
    "language": "polish",
    "number": 928,
    "title": "Pan zawołał sługę swego",
    "source_url": "https://hymnary.org/hymn/SE2002/928"
  },
  {
    "language": "polish",
    "number": 929,
    "title": "Pobożnych dusze żyją",
    "source_url": "https://hymnary.org/hymn/SE2002/929"
  },
  {
    "language": "polish",
    "number": 930,
    "title": "Pochowajmy ciała w grobie",
    "source_url": "https://hymnary.org/hymn/SE2002/930"
  },
  {
    "language": "polish",
    "number": 931,
    "title": "Pokój po bojach, światło po mglach",
    "source_url": "https://hymnary.org/hymn/SE2002/931"
  },
  {
    "language": "polish",
    "number": 932,
    "title": "Raduj się, o duszo moja",
    "source_url": "https://hymnary.org/hymn/SE2002/932"
  },
  {
    "language": "polish",
    "number": 933,
    "title": "Serdecznie pragnę zgonu",
    "source_url": "https://hymnary.org/hymn/SE2002/933"
  },
  {
    "language": "polish",
    "number": 934,
    "title": "Spełniło się! O, tak! Spełniło się!",
    "source_url": "https://hymnary.org/hymn/SE2002/934"
  },
  {
    "language": "polish",
    "number": 935,
    "title": "Tak tedy dokonałem",
    "source_url": "https://hymnary.org/hymn/SE2002/935"
  },
  {
    "language": "polish",
    "number": 936,
    "title": "Tam, w górze nad gwiazdami",
    "source_url": "https://hymnary.org/hymn/SE2002/936"
  },
  {
    "language": "polish",
    "number": 937,
    "title": "Tam wiernych jest zebranie",
    "source_url": "https://hymnary.org/hymn/SE2002/937"
  },
  {
    "language": "polish",
    "number": 938,
    "title": "Tron Twöj ujrzałem",
    "source_url": "https://hymnary.org/hymn/SE2002/938"
  },
  {
    "language": "polish",
    "number": 939,
    "title": "Tu ciało ma kres",
    "source_url": "https://hymnary.org/hymn/SE2002/939"
  },
  {
    "language": "polish",
    "number": 940,
    "title": "Tu na ziemi mam miszkanie",
    "source_url": "https://hymnary.org/hymn/SE2002/940"
  },
  {
    "language": "polish",
    "number": 941,
    "title": "Tu słodko śpij",
    "source_url": "https://hymnary.org/hymn/SE2002/941"
  },
  {
    "language": "polish",
    "number": 942,
    "title": "Twój sługa utrudzony",
    "source_url": "https://hymnary.org/hymn/SE2002/942"
  },
  {
    "language": "polish",
    "number": 943,
    "title": "Ty śpisz, dziecino",
    "source_url": "https://hymnary.org/hymn/SE2002/943"
  },
  {
    "language": "polish",
    "number": 944,
    "title": "Tyś, Chryste, życiem moim",
    "source_url": "https://hymnary.org/hymn/SE2002/944"
  },
  {
    "language": "polish",
    "number": 945,
    "title": "Uczyń ze maną, co cheesz, Panie",
    "source_url": "https://hymnary.org/hymn/SE2002/945"
  },
  {
    "language": "polish",
    "number": 946,
    "title": "W sereach żalość, narzekanie",
    "source_url": "https://hymnary.org/hymn/SE2002/946"
  },
  {
    "language": "polish",
    "number": 947,
    "title": "Wiek życia minął",
    "source_url": "https://hymnary.org/hymn/SE2002/947"
  },
  {
    "language": "polish",
    "number": 948,
    "title": "W spaniałość naszej ziemi",
    "source_url": "https://hymnary.org/hymn/SE2002/948"
  },
  {
    "language": "polish",
    "number": 949,
    "title": "Wszystko mija na tym świecie",
    "source_url": "https://hymnary.org/hymn/SE2002/949"
  },
  {
    "language": "polish",
    "number": 950,
    "title": "Zgasło młode życie moje",
    "source_url": "https://hymnary.org/hymn/SE2002/950"
  },
  {
    "language": "polish",
    "number": 951,
    "title": "Ziarno w Boży grunt rzucajmy",
    "source_url": "https://hymnary.org/hymn/SE2002/951"
  },
  {
